(function(){"use strict";var e=document.querySelectorAll(".pill"),t=document.querySelectorAll(".category-group");if(!e.length||!t.length)return;e.forEach(function(n){n.addEventListener("click",function(){e.forEach(function(e){e.classList.remove("active")}),n.classList.add("active");var s=n.getAttribute("data-filter");t.forEach(function(e){s==="all"||e.getAttribute("data-category")===s?e.classList.remove("hidden"):e.classList.add("hidden")})})})})()